class Solution {

public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root || root == p || root == q)
            return root;

        TreeNode* left = lowestCommonAncestor(root->left, p, q);
        TreeNode* right = lowestCommonAncestor(root->right, p, q);

        if (left && right)
            return root;   // p and q found in different subtrees

        return left ? left : right; // bubble up the found node
    }
};

class Solution {
public:
    int maxDiameter = 0;

    int height(TreeNode* node) {
        if (!node)
            return 0;

        int leftHeight = height(node->left);
        int rightHeight = height(node->right);

        maxDiameter = max(maxDiameter, leftHeight + rightHeight);

        return 1 + max(leftHeight, rightHeight);
    }

    int diameterOfBinaryTree(TreeNode* root) {
        height(root);
        return maxDiameter;
    }
};

class Solution {
public:
    int maxSum = INT_MIN;

    int gain(TreeNode* node) {
        if (!node)
            return 0;

        int leftGain = max(0, gain(node->left));   // ignore negative paths
        int rightGain = max(0, gain(node->right));

        // best path passing through current node
        maxSum = max(maxSum, node->val + leftGain + rightGain);

        // return best single-side path to parent
        return node->val + max(leftGain, rightGain);
    }

    int maxPathSum(TreeNode* root) {
        gain(root);
        return maxSum;
    }
};

class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        if (preorder.empty())
            return nullptr;

        int rootVal = preorder[0];
        TreeNode* root = new TreeNode(rootVal);

        int mid = find(inorder.begin(), inorder.end(), rootVal) - inorder.begin();

        vector<int> leftPreorder(preorder.begin() + 1, preorder.begin() + mid + 1);
        vector<int> rightPreorder(preorder.begin() + mid + 1, preorder.end());

        vector<int> leftInorder(inorder.begin(), inorder.begin() + mid);
        vector<int> rightInorder(inorder.begin() + mid + 1, inorder.end());

        root->left = buildTree(leftPreorder, leftInorder);
        root->right = buildTree(rightPreorder, rightInorder);

        return root;
    }
};

class Codec {
public:
    // Serialize
    string serialize(TreeNode* root) {
        string result;

        function<void(TreeNode*)> dfs = [&](TreeNode* node) {
            if (!node) {
                result += "N,";
                return;
            }

            result += to_string(node->val) + ",";
            dfs(node->left);
            dfs(node->right);
        };

        dfs(root);
        return result;
    }

    // Deserialize
    TreeNode* deserialize(string data) {
        queue<string> vals;
        stringstream ss(data);
        string token;

        while (getline(ss, token, ",")) {
            vals.push(token);
        }

        function<TreeNode*()> dfs = [&]() -> TreeNode* {
            string val = vals.front();
            vals.pop();

            if (val == "N")
                return nullptr;

            TreeNode* node = new TreeNode(stoi(val));
            node->left = dfs();
            node->right = dfs();

            return node;
        };

        return dfs();
    }
};

class Solution {
public:
    void flatten(TreeNode* root) {
        TreeNode* curr = root;

        while (curr) {
            if (curr->left) {
                // Find rightmost node of left subtree
                TreeNode* rightmost = curr->left;
                while (rightmost->right) {
                    rightmost = rightmost->right;
                }

                // Connect rightmost node to original right subtree
                rightmost->right = curr->right;

                // Move left subtree to right
                curr->right = curr->left;
                curr->left = nullptr;
            }

            curr = curr->right;
        }
    }
};

class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> result;
        TreeNode* curr = root;

        while (curr) {
            if (!curr->left) {
                result.push_back(curr->val); // visit node
                curr = curr->right;
            } else {
                // Find inorder predecessor
                TreeNode* pred = curr->left;
                while (pred->right && pred->right != curr) {
                    pred = pred->right;
                }

                if (!pred->right) {
                    pred->right = curr; // create thread
                    curr = curr->left;
                } else {
                    pred->right = nullptr; // remove thread
                    result.push_back(curr->val);
                    curr = curr->right;
                }
            }
        }

        return result;
    }
};

